import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';

// --- MODAL: Bach n-3zlo Sur Place walla Emporter ---
const OrderModal = ({ isOpen, onClose, onConfirm, itemName }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-[2.5rem] p-10 max-w-sm w-full text-center shadow-2xl transform transition-all scale-100">
        <h3 className="text-2xl font-black text-gray-900 italic uppercase mb-2">Commander</h3>
        <p className="text-orange-600 font-bold mb-8 uppercase text-xs tracking-widest">{itemName}</p>

        <div className="space-y-4">
          <button 
            onClick={() => onConfirm('Sur Place')}
            className="w-full py-4 bg-gray-100 hover:bg-orange-600 hover:text-white text-gray-900 rounded-2xl font-black uppercase tracking-widest transition-all duration-300"
          >
            🍽️ Sur Place
          </button>
          <button 
            onClick={() => onConfirm('À Emporter')}
            className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-orange-600 transition-all duration-300"
          >
            🛍️ À Emporter
          </button>
        </div>

        <button onClick={onClose} className="mt-6 text-gray-400 font-bold text-[10px] uppercase tracking-tighter hover:text-red-500 transition">Annuler</button>
      </div>
    </div>
  );
};

// --- MENU PAGE: Updated with Images & Commander ---
const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);

  const handleOrderClick = (item) => {
    setSelectedItem(item);
  };

  const handleConfirmOrder = (type) => {
    addToCart({ ...selectedItem, orderType: type });
    setSelectedItem(null);
    alert(`Ajouté au panier: ${selectedItem.name} (${type})`);
  };

  return (
    <PageLayout title="La Carte">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {categories.flatMap(c => c.dishes).map(item => (
          <div key={item.id} className="group relative bg-black/30 backdrop-blur-lg border border-white/10 rounded-[3rem] overflow-hidden hover:bg-black/40 transition-all duration-500 shadow-2xl">

            {/* TSWIRA: Bach t-ban l-makla mjerjra */}
            <div className="h-64 overflow-hidden relative">
              <img 
                src={item.image || "https://images.unsplash.com/photo-1571407970349-bc81e7e96d47?q=80&w=1000"} 
                alt={item.name} 
                className="w-full h-full object-cover group-hover:scale-110 transition duration-700"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
              <div className="absolute bottom-6 left-6">
                <span className="bg-orange-600 text-white px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest italic shadow-lg">New</span>
              </div>
            </div>

            <div className="p-8 text-center">
              <h3 className="text-2xl font-black text-white italic mb-2 uppercase tracking-tighter">{item.name}</h3>
              <p className="text-gray-400 text-sm mb-6 line-clamp-2 italic opacity-80">{item.description || "Recette secrète avec des ingrédients frais."}</p>

              <div className="flex items-center justify-between mt-4">
                <span className="text-orange-500 font-black text-2xl tracking-tighter">{item.price} DH</span>
                {/* BUTTON: Commander */}
                <button 
                  onClick={() => handleOrderClick(item)}
                  className="bg-white text-black px-8 py-3 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 hover:text-white transition shadow-xl transform active:scale-90"
                >
                  Commander
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      <OrderModal 
        isOpen={!!selectedItem} 
        onClose={() => setSelectedItem(null)} 
        onConfirm={handleConfirmOrder}
        itemName={selectedItem?.name}
      />
    </PageLayout>
  );
};

